export const NAVIGATION_GLYPH_IDS = Object.keys(NAVIGATION_GLYPHS);
export function isNavigationGlyph(shape) {
    return Object.prototype.hasOwnProperty.call(NAVIGATION_GLYPHS, shape);
}
const compiled = new Map();
const pointCache = new Map();
const fract = (value) => value - Math.floor(value);
function sampleGlyph(shape, count) {
    const key = `${shape}:${count}`;
    const cached = pointCache.get(key);
    if (cached)
        return cached;
    let glyph = compiled.get(shape);
    if (!glyph) {
        const segments = [], patches = [];
        let area = 0;
        for (const path of NAVIGATION_GLYPHS[shape].ink.strokes) {
            for (let j = 1; j < path.points.length; j++) {
                const a = path.points[j - 1], b = path.points[j];
                const length = Math.hypot(b[0] - a[0], b[1] - a[1]);
                if (length < 0.00001)
                    continue;
                area += length * path.width;
                segments.push({
                    a,
                    b,
                    length,
                    width: path.width,
                    depth: path.depth,
                    end: area,
                });
            }
        }
        for (const patch of NAVIGATION_GLYPHS[shape].ink.triangles) {
            const [a, b, c] = patch.vertices;
            area +=
                Math.abs((b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])) / 2;
            patches.push({ ...patch, end: area });
        }
        glyph = { segments, patches, area };
        compiled.set(shape, glyph);
    }
    let segmentIndex = 0, patchIndex = 0;
    const points = Array.from({ length: count }, (_, i) => {
        const target = ((i + 0.5) / count) * glyph.area;
        const segments = glyph.segments;
        if (target <= (segments[segments.length - 1]?.end ?? 0)) {
            while (segments[segmentIndex].end < target)
                segmentIndex++;
            const p = segments[segmentIndex];
            const t = (target - (p.end - p.length * p.width)) / (p.length * p.width);
            const offset = (fract(i * 0.61803398875 + 0.3) - 0.5) * p.width;
            const dx = (p.b[0] - p.a[0]) / p.length, dy = (p.b[1] - p.a[1]) / p.length;
            return {
                x: (p.a[0] + (p.b[0] - p.a[0]) * t - dy * offset - 12) / 12,
                y: (p.a[1] + (p.b[1] - p.a[1]) * t + dx * offset - 12) / 12,
                z: p.depth,
            };
        }
        while (glyph.patches[patchIndex].end < target)
            patchIndex++;
        const p = glyph.patches[patchIndex], [a, b, c] = p.vertices;
        const u = Math.sqrt(fract(i * 0.754877666 + 0.4)), v = fract(i * 0.569840291 + 0.2);
        return {
            x: ((1 - u) * a[0] + u * (1 - v) * b[0] + u * v * c[0] - 12) / 12,
            y: ((1 - u) * a[1] + u * (1 - v) * b[1] + u * v * c[1] - 12) / 12,
            z: p.depth,
        };
    });
    if (pointCache.size >= 128)
        pointCache.delete(pointCache.keys().next().value);
    pointCache.set(key, points);
    return points;
}
export function getNavigationGlyphPoints(shape, count, time) {
    const flow = NAVIGATION_GLYPHS[shape].flow;
    return sampleGlyph(shape, count).map((p, i) => ({
        ...p,
        z: flow && p.z > 0
            ? p.z + 0.3 * Math.sin((i / count) * Math.PI * 2 - time * 2)
            : p.z,
    }));
}
